mapper.select:
SELECT r.user_id AS userId, r.segment_code AS segmentCode, r.segment_name AS segmentName, r.cluster_index AS clusterIndex, r.distance_to_center AS distanceToCenter, r.confidence_score AS confidenceScore, r.is_cold_start AS isColdStart, r.persona_summary AS personaSummary, r.sort_order AS sortOrder, u.username AS username, u.nickname AS nickname, u.avatar AS avatar, u.phone AS phone, u.status AS userStatus, f.order_count_90d AS orderCount90d, f.order_amount_90d AS orderAmount90d, f.avg_order_amount_90d AS avgOrderAmount90d, f.behavior_count_30d AS behaviorCount30d, f.active_days_30d AS activeDays30d, f.recency_order_days AS recencyOrderDays, f.recency_behavior_days AS recencyBehaviorDays FROM analytics_kmeans_user_result r LEFT JOIN `user` u ON u.id = r.user_id LEFT JOIN analytics_kmeans_feature_snapshot f ON f.task_id = r.task_id AND f.user_id = r.user_id WHERE r.task_id = #{taskId}
AND r.segment_code = #{segmentCode}
ORDER BY r.sort_order ASC, r.confidence_score DESC, r.user_id DESC

SELECT r.user_id FROM analytics_kmeans_user_result r INNER JOIN `user` u ON u.id = r.user_id AND u.status = 1 AND (u.deleted = 0 OR u.deleted IS NULL) WHERE r.task_id = #{taskId} AND r.segment_code IN
#{segmentCode}
ORDER BY r.sort_order ASC, r.confidence_score DESC, r.user_id DESC
